//! LutMap's forward transformation against C's, bit for bit: between nodes
//! with an increment that is not a power of two, beyond either end, on the
//! last node beside a bad entry, and at half increments for
//! nearest-neighbour interpolation (lutmap.c Transform).
//!
//! `lutmap_forward_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/lutmap_forward_probe.c`.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "lutmap_forward_oracle/cases.rs"]
mod cases;

use ast_core::mappings::{LutInterp, LutMap, Mapping};

#[test]
fn forward_matches_the_c_library_bit_for_bit() {
    let mut failures = Vec::new();
    for &(name, lut, start, inc, nearest, input, want) in cases::CASES {
        let mut lm = LutMap::new(lut, start, inc).unwrap();
        lm.set_interp(if nearest {
            LutInterp::Nearest
        } else {
            LutInterp::Linear
        });
        let got = lm.tran1(input, true).unwrap();
        for ((x, g), w) in input.iter().zip(&got).zip(want) {
            if g.to_bits() != w.to_bits() {
                failures.push(format!("{name} at {x}: {g:e}, C {w:e}"));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
